mapper.insert:
insert into ssm_hot_table_info( hot_table_id, source_table_name, hot_table_name, hot_db_engine, hot_data_init_days, data_min_date, data_max_date, etl_job_name, is_active, created_by, created_time ) select md5(uuid()) as hot_table_id, t1.source_table_name, concat( 'bi_hot.h_', substring(t1.source_table_name, locate('.', t1.source_table_name) + 1, length(t1.source_table_name) - locate('.', t1.source_table_name)) ) as hot_table_name, 'trino' as hot_db_engine, t1.hot_data_init_days, date_format(date_sub(curdate(), interval t1.hot_data_init_days day), '%Y-%m-%d') as data_min_date, date_format(date_sub(curdate(), interval 1 day), '%Y-%m-%d') as data_max_date, upper( concat('HOT_H_', substring(t1.source_table_name, locate('.', t1.source_table_name) + 1, length(t1.source_table_name) - locate('.', t1.source_table_name)) ) ) as etl_job_name, 1 as is_active, '${hotTableOwner}' as created_by, now() as created_time from ssm_hot_table_source t1 where t1.support_hot_db_engine like '%trino%' and t1.is_active = 1
and t1.source_table_name in (
#{item}
)
union all select md5(uuid()) as hot_table_id, t1.source_table_name, concat( 'bi_hot.h_', substring(t1.source_table_name, locate('.', t1.source_table_name) + 1, length(t1.source_table_name) - locate('.', t1.source_table_name)) ) as hot_table_name, 'doris' as hot_db_engine, t1.hot_data_init_days, date_format(date_sub(curdate(), interval t1.hot_data_init_days day), '%Y-%m-%d') as data_min_date, date_format(date_sub(curdate(), interval 1 day), '%Y-%m-%d') as data_max_date, upper( concat('DRH_H_', substring(t1.source_table_name, locate('.', t1.source_table_name) + 1, length(t1.source_table_name) - locate('.', t1.source_table_name)) ) ) as etl_job_name, 1 as is_active, '${hotTableOwner}' as created_by, now() as created_time from ssm_hot_table_source t1 where t1.support_hot_db_engine like '%doris%' and t1.is_active = 1
and t1.source_table_name in (
#{item}
)

mapper.update:
update ssm_hot_table_info
set data_finish_time = #{dataFinishTime}
where etl_job_name = #{etlJobName}

update ssm_hot_table_info set data_max_date = date_format(date_sub(curdate(), interval 1 day), '%Y-%m-%d'), data_finish_time = null , is_active = 1, updated_time = now(), updated_by = '${hotTableOwner}' where 1=1
and source_table_name in (
#{item}
)

UPDATE ssm_hot_table_info t1 INNER JOIN ( SELECT source_table_name, DATE_FORMAT( DATE_SUB( CURDATE(), INTERVAL hot_data_max_days DAY ), '%Y-%m-%d' ) AS hot_data_min_date FROM ssm_hot_table_source WHERE data_update_mode = 'incremental' AND source_table_name IN (
#{item}
) ) t2 ON t1.source_table_name = t2.source_table_name SET t1.data_min_date = t2.hot_data_min_date WHERE t1.data_min_date <= t2.hot_data_min_date AND t1.source_table_name IN (
#{item}
)

update ssm_hot_table_info
set data_min_date = #{minDate}
where source_table_name = #{sourceTableName}
